'use strict';

const W = 120, H = 76, N = W * H;
const TICKS_PER_GEN = 300;

function mulberry32(a) {
  return function () {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
function gauss(rng) {
  let u = 0, v = 0;
  while (u === 0) u = rng();
  while (v === 0) v = rng();
  return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
}
const clamp = (v, a, b) => v < a ? a : v > b ? b : v;
const TAU = Math.PI * 2;

const BASES = {
  prey: { speed: 0.42, vision: 0.5, metabolism: 0.45, repro: 0.5 },
  pred: { speed: 0.62, vision: 0.68, metabolism: 0.5, repro: 0.55 },
};
const GENE_KEYS = ['speed', 'vision', 'metabolism', 'repro'];

function makeGenome(rng, species) {
  const b = BASES[species];
  const g = {};
  for (const k of GENE_KEYS) g[k] = clamp(b[k] + gauss(rng) * 0.09, 0.05, 0.95);
  return g;
}

class Sim {
  constructor(opts = {}) {
    this.seed = opts.seed ?? 0x7A3F09C1;
    this.mutation = opts.mutation ?? 0.045;
    this.regrowth = opts.regrowth ?? 4.2;
    this.eventInterval = opts.eventInterval ?? 9;
    this.targetGenerations = opts.targetGenerations ?? 40;
    this.enabled = opts.enabled ?? { drought: true, plague: true, frost: true };
    this.rng = mulberry32(this.seed);
    this.gen = 0;
    this.tick = 0;
    this.paused = false;
    this.finished = false;
    this.plants = new Float32Array(N);
    this.prey = [];
    this.pred = [];
    this.events = [];
    this.history = [];
    this.eventCycle = 0;
    this.drought = 0;
    this.lastEventGen = 0;
    this.init();
    this.sample();
  }

  init() {
    const rng = this.rng;
    // lichen clusters
    this.plants.fill(0);
    const clusters = 54;
    for (let c = 0; c < clusters; c++) {
      const cx = rng() * W, cy = rng() * H;
      const rad = 6 + rng() * 16;
      const amp = 0.45 + rng() * 0.55;
      const x0 = Math.max(0, Math.floor(cx - rad)), x1 = Math.min(W - 1, Math.ceil(cx + rad));
      const y0 = Math.max(0, Math.floor(cy - rad)), y1 = Math.min(H - 1, Math.ceil(cy + rad));
      for (let y = y0; y <= y1; y++) {
        for (let x = x0; x <= x1; x++) {
          let dx = x - cx, dy = y - cy;
          if (dx > W / 2) dx -= W; if (dx < -W / 2) dx += W;
          if (dy > H / 2) dy -= H; if (dy < -H / 2) dy += H;
          const d = Math.sqrt(dx * dx + dy * dy);
          if (d < rad) {
            const v = amp * Math.pow(1 - d / rad, 1.4);
            const i = y * W + x;
            if (v > this.plants[i]) this.plants[i] = v;
          }
        }
      }
    }
    for (let i = 0; i < N; i++) {
      if (this.plants[i] < 0.03 && rng() < 0.25) this.plants[i] = 0.08 + rng() * 0.3;
    }

    for (let i = 0; i < 190; i++) this.prey.push(this.makeAgent('prey'));
    for (let i = 0; i < 30; i++) this.pred.push(this.makeAgent('pred'));
  }

  makeAgent(species, x, y, genes) {
    const rng = this.rng;
    const g = genes || makeGenome(rng, species);
    return {
      species,
      x: x ?? rng() * W,
      y: y ?? rng() * H,
      heading: rng() * TAU,
      genes: g,
      energy: species === 'prey' ? 0.85 + rng() * 0.25 : 1.3 + rng() * 0.3,
      age: 0,
      cooldown: rng() * 60,
      biteCd: 0,
      scan: 0,
      target: null,
      fleeing: false,
      alive: true,
      lastMeal: 0,
    };
  }

  idx(x, y) {
    const ix = ((x | 0) % W + W) % W;
    const iy = ((y | 0) % H + H) % H;
    return iy * W + ix;
  }
  plantAt(x, y) { return this.plants[this.idx(x, y)]; }

  buildHash(list, cell = 10) {
    const hx = Math.ceil(W / cell), hy = Math.ceil(H / cell);
    const buckets = new Array(hx * hy);
    for (let i = 0; i < buckets.length; i++) buckets[i] = [];
    for (const a of list) {
      if (!a.alive) continue;
      const bx = ((a.x / cell) | 0) % hx, by = ((a.y / cell) | 0) % hy;
      buckets[by * hx + bx].push(a);
    }
    return { buckets, hx, hy, cell };
  }

  nearestFromHash(hash, x, y, radius) {
    const { buckets, hx, hy, cell } = hash;
    const cx = (x / cell) | 0, cy = (y / cell) | 0;
    const r = Math.ceil(radius / cell);
    let best = null, bestD = radius * radius;
    for (let oy = -r; oy <= r; oy++) {
      for (let ox = -r; ox <= r; ox++) {
        const bx = ((cx + ox) % hx + hx) % hx;
        const by = ((cy + oy) % hy + hy) % hy;
        const arr = buckets[by * hx + bx];
        for (const a of arr) {
          if (!a.alive) continue;
          let dx = a.x - x, dy = a.y - y;
          if (dx > W / 2) dx -= W; if (dx < -W / 2) dx += W;
          if (dy > H / 2) dy -= H; if (dy < -H / 2) dy += H;
          const d = dx * dx + dy * dy;
          if (d < bestD) { bestD = d; best = a; }
        }
      }
    }
    return best ? { agent: best, dist: Math.sqrt(bestD) } : null;
  }

  step() {
    if (this.finished) return;
    const rng = this.rng;
    this.tick++;

    // plant growth
    const growth = this.drought > 0 ? this.regrowth * 0.22 : this.regrowth;
    const events = Math.round(growth * 46);
    for (let k = 0; k < events; k++) {
      const i = (rng() * N) | 0;
      const p = this.plants[i];
      if (p < 1) this.plants[i] = p + (0.028 + 0.02 * rng()) * (1 - p) * (0.35 + 0.65 * p);
    }
    if (this.drought > 0) this.drought--;

    const preyHash = this.buildHash(this.prey);
    const predHash = this.buildHash(this.pred);

    // prey
    for (const a of this.prey) {
      if (!a.alive) continue;
      a.age++; a.cooldown--; a.biteCd--; a.scan--;
      const g = a.genes;
      const speedMax = 0.28 + g.speed * 1.05;
      const vision = 3.2 + g.vision * 13;
      let desired = a.heading;
      let moving = 0;

      const threat = this.nearestFromHash(predHash, a.x, a.y, vision * 0.72);
      a.fleeing = false;
      if (threat) {
        const dx = a.x - threat.agent.x, dy = a.y - threat.agent.y;
        desired = Math.atan2(dy, dx) + (rng() - 0.5) * 0.5;
        a.fleeing = true;
        a.target = null;
      } else {
        if (a.scan <= 0 || !a.target) {
          a.scan = 7 + ((rng() * 8) | 0);
          let bx = 0, by = 0, best = this.plantAt(a.x, a.y) * 1.15;
          for (let s = 0; s < 7; s++) {
            const ang = rng() * TAU, r = Math.sqrt(rng()) * vision;
            const tx = a.x + Math.cos(ang) * r, ty = a.y + Math.sin(ang) * r;
            const v = this.plantAt(tx, ty);
            if (v > best) { best = v; bx = tx; by = ty; }
          }
          a.target = best > 0.05 ? { x: bx, y: by } : null;
        }
        if (a.target) {
          let dx = a.target.x - a.x, dy = a.target.y - a.y;
          if (dx > W / 2) dx -= W; if (dx < -W / 2) dx += W;
          if (dy > H / 2) dy -= H; if (dy < -H / 2) dy += H;
          const d = Math.hypot(dx, dy);
          if (d < 1.3) { a.scan = 0; a.target = null; }
          else desired = Math.atan2(dy, dx);
        } else {
          desired = a.heading + (rng() - 0.5) * 0.55;
        }
      }

      // turn toward desired
      let diff = ((desired - a.heading + Math.PI * 3) % TAU) - Math.PI;
      a.heading += clamp(diff, -0.34, 0.34);
      const spd = speedMax * (a.fleeing ? 1.28 : 1) * (a.energy < 0.28 ? 0.62 : 1);
      a.x += Math.cos(a.heading) * spd;
      a.y += Math.sin(a.heading) * spd;
      if (a.x < 0) a.x += W; if (a.x >= W) a.x -= W;
      if (a.y < 0) a.y += H; if (a.y >= H) a.y -= H;
      moving = 1;

      // eat
      if (a.biteCd <= 0) {
        const i = this.idx(a.x, a.y);
        const available = this.plants[i];
        if (available > 0.02) {
          const bite = Math.min(available, 0.034);
          this.plants[i] = available - bite;
          a.energy = Math.min(2.6, a.energy + bite * 5.4);
          a.lastMeal = this.gen;
          a.biteCd = 3;
        }
      }

      // metabolism
      const cost = 0.0019 + 0.0032 * g.metabolism + 0.0024 * g.speed + 0.0011 * g.vision +
        (a.fleeing ? 0.0022 : 0);
      a.energy -= cost;

      // reproduce
      if (a.energy > 0.95 + g.repro * 0.95 && a.cooldown <= 0 && this.prey.length < 1000) {
        const childEnergy = a.energy * 0.36;
        a.energy *= 0.56;
        a.cooldown = 55 + ((rng() * 45) | 0);
        const child = this.makeAgent('prey', a.x + (rng() - 0.5) * 2, a.y + (rng() - 0.5) * 2, this.mutate(g));
        child.energy = childEnergy;
        child.cooldown = 45;
        this.prey.push(child);
      }

      if (a.energy <= 0 || a.age > 620 || (this.prey.length > 900 && rng() < 0.001)) a.alive = false;
    }

    // predators
    for (const a of this.pred) {
      if (!a.alive) continue;
      a.age++; a.cooldown--; a.scan--;
      const g = a.genes;
      const speedMax = 0.42 + g.speed * 1.16;
      const vision = 4 + g.vision * 16;
      let desired = a.heading;
      const near = this.nearestFromHash(preyHash, a.x, a.y, vision);
      a.target = near ? { x: near.agent.x, y: near.agent.y } : null;
      a.fleeing = false;
      if (near) {
        let dx = near.agent.x - a.x, dy = near.agent.y - a.y;
        if (dx > W / 2) dx -= W; if (dx < -W / 2) dx += W;
        if (dy > H / 2) dy -= H; if (dy < -H / 2) dy += H;
        desired = Math.atan2(dy, dx);
      } else {
        desired = a.heading + (rng() - 0.5) * 0.3;
      }
      let diff = ((desired - a.heading + Math.PI * 3) % TAU) - Math.PI;
      a.heading += clamp(diff, -0.28, 0.28);
      const spd = speedMax * (near && near.dist < 5 ? 1.32 : 1) * (a.energy < 0.3 ? 0.6 : 1);
      a.x += Math.cos(a.heading) * spd;
      a.y += Math.sin(a.heading) * spd;
      if (a.x < 0) a.x += W; if (a.x >= W) a.x -= W;
      if (a.y < 0) a.y += H; if (a.y >= H) a.y -= H;

      if (near && near.dist < 1.45) {
        const victim = near.agent;
        if (victim.alive) {
          victim.alive = false;
          a.energy = Math.min(3.2, a.energy + 0.22 + victim.energy * 0.62);
          a.lastMeal = this.gen;
        }
      }

      const cost = 0.0021 + 0.0038 * g.metabolism + 0.0036 * g.speed + 0.0016 * g.vision;
      a.energy -= cost;

      if (a.energy > 1.35 + g.repro * 1.1 && a.cooldown <= 0 && this.pred.length < 260) {
        const childEnergy = a.energy * 0.34;
        a.energy *= 0.55;
        a.cooldown = 95 + ((rng() * 70) | 0);
        const child = this.makeAgent('pred', a.x + (rng() - 0.5) * 2.4, a.y + (rng() - 0.5) * 2.4, this.mutate(g));
        child.energy = childEnergy;
        child.cooldown = 80;
        this.pred.push(child);
      }

      if (a.energy <= 0 || a.age > 980) a.alive = false;
    }

    // compaction occasionally
    if ((this.tick & 63) === 0) {
      this.prey = this.prey.filter(a => a.alive);
      this.pred = this.pred.filter(a => a.alive);
    }

    // generation boundary
    if (this.tick % TICKS_PER_GEN === 0) {
      this.gen++;
      this.prey = this.prey.filter(a => a.alive);
      this.pred = this.pred.filter(a => a.alive);
      this.sample();
      this.maybeEvent();
      if (this.gen >= this.targetGenerations) this.finished = true;
    }
  }

  mutate(g) {
    const rate = this.mutation;
    const out = {};
    for (const k of GENE_KEYS) out[k] = clamp(g[k] + gauss(this.rng) * rate * 0.38, 0.03, 0.97);
    return out;
  }

  maybeEvent() {
    if (this.gen <= 0 || this.eventInterval <= 0) return;
    if (this.gen % this.eventInterval !== 0) return;
    const types = ['drought', 'plague', 'frost'].filter(t => this.enabled[t]);
    if (!types.length) return;
    // find next enabled after previous
    let type = null;
    for (let k = 1; k <= 3; k++) {
      const t = ['drought', 'plague', 'frost'][(this.eventCycle + k) % 3];
      if (this.enabled[t]) { type = t; this.eventCycle = (this.eventCycle + k) % 3; break; }
    }
    if (!type) return;
    const before = { prey: this.prey.filter(a => a.alive).length, pred: this.pred.filter(a => a.alive).length };
    let plantBefore = 0, plantAfter = 0;
    for (let i = 0; i < N; i++) plantBefore += this.plants[i];
    let losses = { prey: 0, pred: 0, plants: 0 };
    if (type === 'drought') {
      for (let i = 0; i < N; i++) this.plants[i] *= 0.55;
      this.drought = TICKS_PER_GEN * 2;
      for (let i = 0; i < N; i++) plantAfter += this.plants[i];
      losses.plants = (plantBefore - plantAfter) / Math.max(1, plantBefore);
    } else if (type === 'plague') {
      let killed = 0;
      for (const a of this.prey) if (a.alive && this.rng() < 0.5) { a.alive = false; killed++; }
      this.prey = this.prey.filter(a => a.alive);
      losses.prey = before.prey ? killed / before.prey : 0;
    } else {
      for (const a of this.prey) if (a.alive && this.rng() < 0.3) a.alive = false;
      for (const a of this.pred) if (a.alive && this.rng() < 0.28) a.alive = false;
      for (let i = 0; i < N; i++) this.plants[i] *= 0.78;
      this.prey = this.prey.filter(a => a.alive);
      this.pred = this.pred.filter(a => a.alive);
      losses.prey = 0.3; losses.pred = 0.28; losses.plants = 0.22;
    }
    this.events.push({ gen: this.gen, type, losses });
    this.lastEventGen = this.gen;
  }

  sample() {
    const count = arr => arr.filter(a => a.alive).length;
    let plant = 0;
    for (let i = 0; i < N; i++) plant += this.plants[i];
    const genes = {};
    for (const sp of ['prey', 'pred']) {
      const arr = (sp === 'prey' ? this.prey : this.pred).filter(a => a.alive);
      genes[sp] = {};
      for (const k of GENE_KEYS) {
        let mean = 0;
        for (const a of arr) mean += a.genes[k];
        mean /= Math.max(1, arr.length);
        let varr = 0;
        for (const a of arr) varr += (a.genes[k] - mean) ** 2;
        varr /= Math.max(1, arr.length);
        genes[sp][k] = { mean: arr.length ? mean : 0, sd: arr.length ? Math.sqrt(varr) : 0 };
      }
    }
    this.history.push({
      gen: this.gen,
      plants: plant / N,
      prey: count(this.prey),
      pred: count(this.pred),
      genes,
    });
  }

  stateHash() {
    let h = 2166136261 >>> 0;
    for (let i = 0; i < N; i += 3) {
      h ^= Math.round(this.plants[i] * 255);
      h = Math.imul(h, 16777619) >>> 0;
    }
    for (const a of this.prey) {
      h ^= (a.x * 131 + a.y * 17 + a.energy * 977) | 0;
      h = Math.imul(h, 16777619) >>> 0;
    }
    for (const a of this.pred) {
      h ^= (a.x * 131 + a.y * 17 + a.energy * 977) | 0;
      h = Math.imul(h, 16777619) >>> 0;
    }
    return h >>> 0;
  }
}

function trial(seed, gens = 40) {
  const sim = new Sim({ seed, targetGenerations: gens });
  const rows = [];
  let guard = 0;
  while (!sim.finished && guard++ < 20000) sim.step();
  console.log('seed', seed.toString(16), 'hash', sim.stateHash().toString(16));
  for (const h of sim.history) {
    if (h.gen % 2 === 0) {
      const fmt = (sp, k) => h.genes[sp][k].mean.toFixed(2);
      console.log(
        String(h.gen).padStart(3),
        'plants', (h.plants * 100).toFixed(0).padStart(3) + '%',
        'prey', String(h.prey).padStart(3),
        'pred', String(h.pred).padStart(3),
        '| pv', fmt('prey', 'speed'), fmt('prey', 'vision'), fmt('prey', 'metabolism'), fmt('prey', 'repro'),
        '| pr', fmt('pred', 'speed'), fmt('pred', 'vision'), fmt('pred', 'metabolism'), fmt('pred', 'repro')
      );
    }
  }
  console.log('events', sim.events.map(e => `${e.type}@${e.gen}`).join(' '));
}

trial(0x7A3F09C1);

