input.content:
'use strict';
const W = 120, H = 76, N = W * H;
const TICKS_PER_GEN = 300;
const TAU = Math.PI * 2;
const GENE_KEYS = ['speed', 'vision', 'metabolism', 'repro'];
const clamp = (v, a, b) => v < a ? a : v > b ? b : v;

function mulberry32(a) {
  return function () {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
function gauss(rng) {
  let u = 0, v = 0;
  while (u === 0) u = rng();
  while (v === 0) v = rng();
  return Math.sqrt(-2 * Math.log(u)) * Math.cos(TAU * v);
}

const BASES = {
  prey: { speed: 0.42, vision: 0.5, metabolism: 0.45, repro: 0.5 },
  pred: { speed: 0.62, vision: 0.68, metabolism: 0.5, repro: 0.55 },
};
function makeGenome(rng, species, spread = 0.08) {
  const b = BASES[species], g = {};
  for (const k of GENE_KEYS) g[k] = clamp(b[k] + gauss(rng) * spread, 0.05, 0.95);
  return g;
}

const defaults = {
  seed: 0x7a3f09c1,
  mutation: 0.045,
  regrowth: 5,
  eventInterval: 9,
  targetGenerations: 40,
  preyInit: 170,
  predInit: 24,
  enabled: { drought: true, plague: true, frost: true },
};

class Sim {
  constructor(opts = {}) {
    Object.assign(this, defaults, opts);
    this.rng = mulberry32(this.seed);
    this.gen = 0; this.tick = 0; this.finished = false;
    this.plants = new Float32Array(N);
    this.prey = []; this.pred = [];
    this.events = []; this.history = [];
    this.eventCycle = 0; this.drought = 0;
    this.init(); this.sample();
  }

  init() {
    const rng = this.rng;
    this.plants.fill(0);
    for (let c = 0; c < 54; c++) {
      const cx = rng() * W, cy = rng() * H;
      const rad = 6 + rng() * 16, amp = 0.45 + rng() * 0.55;
      for (let y = 0; y < H; y++) {
        let dy = y - cy; if (dy > H / 2) dy -= H; if (dy < -H / 2) dy += H;
        if (Math.abs(dy) > rad) continue;
        for (let x = 0; x < W; x++) {
          let dx = x - cx; if (dx > W / 2) dx -= W; if (dx < -W / 2) dx += W;
          const d = Math.hypot(dx, dy);
          if (d < rad) {
            const v = amp * Math.pow(1 - d / rad, 1.4);
            const i = y * W + x;
            if (v > this.plants[i]) this.plants[i] = v;
          }
        }
      }
    }
    for (let i = 0; i < N; i++) if (this.plants[i] < 0.03 && rng() < 0.22) this.plants[i] = 0.06 + rng() * 0.24;
    for (let i = 0; i < this.preyInit; i++) this.prey.push(this.makeAgent('prey'));
    for (let i = 0; i < this.predInit; i++) this.pred.push(this.makeAgent('pred'));
  }

  makeAgent(species, x, y, genes) {
    const rng = this.rng;
    return {
      species,
      x: x ?? rng() * W, y: y ?? rng() * H,
      heading: rng() * TAU,
      genes: genes || makeGenome(rng, species),
      energy: species === 'prey' ? 0.62 + rng() * 0.2 : 0.95 + rng() * 0.3,
      age: 0,
      cooldown: rng() * 90,
      biteCd: (rng() * 4) | 0,
      killCd: (rng() * 40) | 0,
      scan: 0,
      target: null,
      fleeing: false,
      alive: true,
      lastMeal: 0,
    };
  }
  idx(x, y) {
    const ix = ((x | 0) % W + W) % W, iy = ((y | 0) % H + H) % H;
    return iy * W + ix;
  }
  plantAt(x, y) { return this.plants[this.idx(x, y)]; }

  buildHash(list, cell = 12) {
    const hx = Math.ceil(W / cell), hy = Math.ceil(H / cell);
    const buckets = new Array(hx * hy);
    for (let i = 0; i < buckets.length; i++) buckets[i] = [];
    for (const a of list) {
      if (!a.alive) continue;
      const bx = ((a.x / cell) | 0) % hx, by = ((a.y / cell) | 0) % hy;
      buckets[by * hx + bx].push(a);
    }
    return { buckets, hx, hy, cell };
  }
  nearestFromHash(hash, x, y, radius) {
    const { buckets, hx, hy, cell } = hash;
    const r = Math.ceil(radius / cell);
    const cx = (x / cell) | 0, cy = (y / cell) | 0;
    let best = null, bestD = radius * radius;
    for (let oy = -r; oy <= r; oy++) for (let ox = -r; ox <= r; ox++) {
      const bx = ((cx + ox) % hx + hx) % hx, by = ((cy + oy) % hy + hy) % hy;
      for (const a of buckets[by * hx + bx]) {
        if (!a.alive) continue;
        let dx = a.x - x, dy = a.y - y;
        if (dx > W / 2) dx -= W; if (dx < -W / 2) dx += W;
        if (dy > H / 2) dy -= H; if (dy < -H / 2) dy += H;
        const d = dx * dx + dy * dy;
        if (d < bestD) { bestD = d; best = a; }
      }
    }
    return best ? { agent: best, dist: Math.sqrt(bestD) } : null;
  }

  step() {
    if (this.finished) return;
    const rng = this.rng;
    this.tick++;

    const growth = this.drought > 0 ? this.regrowth * 0.25 : this.regrowth;
    const events = Math.round(growth * 58);
    for (let k = 0; k < events; k++) {
      const i = (rng() * N) | 0, p = this.plants[i];
      if (p < 1) this.plants[i] = p + (0.03 + 0.022 * rng()) * (1 - p) * (0.3 + 0.7 * p);
    }
    if (this.drought > 0) this.drought--;

    const preyHash = this.buildHash(this.prey);
    const predHash = this.buildHash(this.pred);

    for (const a of this.prey) {
      if (!a.alive) continue;
      a.age++; a.cooldown--; a.biteCd--; a.scan--;
      const g = a.genes;
      const speedMax = 0.30 + g.speed * 1.02;
      const vision = 3.2 + g.vision * 13;
      let desired = a.heading, fleeing = false;

      const threat = this.nearestFromHash(predHash, a.x, a.y, vision * 0.7);
      if (threat) {
        desired = Math.atan2(a.y - threat.agent.y, a.x - threat.agent.x) + (rng() - 0.5) * 0.5;
        fleeing = true; a.target = null;
      } else {
        if (a.scan <= 0) {
          a.scan = 8 + ((rng() * 8) | 0);
          let bx = 0, by = 0, best = this.plantAt(a.x, a.y) * 1.2;
          for (let s = 0; s < 7; s++) {
            const ang = rng() * TAU, r = Math.sqrt(rng()) * vision;
            const tx = a.x + Math.cos(ang) * r, ty = a.y + Math.sin(ang) * r;
            const v = this.plantAt(tx, ty);
            if (v > best) { best = v; bx = tx; by = ty; }
          }
          a.target = best > 0.04 ? { x: bx, y: by } : null;
        }
        if (a.target) {
          let dx = a.target.x - a.x, dy = a.target.y - a.y;
          if (dx > W / 2) dx -= W; if (dx < -W / 2) dx += W;
          if (dy > H / 2) dy -= H; if (dy < -H / 2) dy += H;
          if (Math.hypot(dx, dy) < 1.4) { a.scan = 0; a.target = null; }
          else desired = Math.atan2(dy, dx);
        } else desired = a.heading + (rng() - 0.5) * 0.55;
      }
      a.fleeing = fleeing;
      let diff = ((desired - a.heading + Math.PI * 3) % TAU) - Math.PI;
      a.heading += clamp(diff, -0.36, 0.36);
      const spd = speedMax * (fleeing ? 1.22 : 1) * (a.energy < 0.25 ? 0.6 : 1);
      a.x = (a.x + Math.cos(a.heading) * spd + W) % W;
      a.y = (a.y + Math.sin(a.heading) * spd + H) % H;

      if (a.biteCd <= 0) {
        const i = this.idx(a.x, a.y), avail = this.plants[i];
        if (avail > 0.02) {
          const bite = Math.min(avail, 0.03);
          this.plants[i] = avail - bite;
          a.energy = Math.min(2.0, a.energy + bite * 3.9);
          a.lastMeal = this.gen;
          a.biteCd = 7;
        }
      }
      a.energy -= 0.0018 + 0.0032 * g.metabolism + 0.0022 * g.speed + 0.0010 * g.vision + (fleeing ? 0.0018 : 0);

      if (a.energy > 1.3 + g.repro * 0.75 && a.cooldown <= 0 && this.prey.length < 950) {
        const childEnergy = a.energy * 0.34;
        a.energy *= 0.55;
        a.cooldown = 125 + ((rng() * 60) | 0);
        const child = this.makeAgent('prey', a.x + (rng() - 0.5) * 2, a.y + (rng() - 0.5) * 2, this.mutate(g));
        child.energy = childEnergy; child.cooldown = 100;
        this.prey.push(child);
      }
      if (a.energy <= 0 || a.age > 700) a.alive = false;
    }

    for (const a of this.pred) {
      if (!a.alive) continue;
      a.age++; a.cooldown--; a.killCd--;
      const g = a.genes;
      const speedMax = 0.32 + g.speed * 0.98;
      const vision = 4 + g.vision * 16;
      const near = this.nearestFromHash(preyHash, a.x, a.y, vision);
      let desired = a.heading;
      if (near) {
        let dx = near.agent.x - a.x, dy = near.agent.y - a.y;
        if (dx > W / 2) dx -= W; if (dx < -W / 2) dx += W;
        if (dy > H / 2) dy -= H; if (dy < -H / 2) dy += H;
        desired = Math.atan2(dy, dx);
      } else desired = a.heading + (rng() - 0.5) * 0.3;
      let diff = ((desired - a.heading + Math.PI * 3) % TAU) - Math.PI;
      a.heading += clamp(diff, -0.3, 0.3);
      const spd = speedMax * (near && near.dist < 5 ? 1.24 : 1) * (a.energy < 0.25 ? 0.6 : 1);
      a.x = (a.x + Math.cos(a.heading) * spd + W) % W;
      a.y = (a.y + Math.sin(a.heading) * spd + H) % H;

      if (near && near.dist < 1.1 && a.killCd <= 0 && near.agent.alive) {
        const victim = near.agent;
        victim.alive = false;
        a.energy = Math.min(2.6, a.energy + 0.16 + victim.energy * 0.48);
        a.lastMeal = this.gen;
        a.killCd = 75 + ((rng() * 35) | 0);
      }
      a.energy -= 0.0020 + 0.0038 * g.metabolism + 0.0032 * g.speed + 0.0015 * g.vision;

      if (a.energy > 1.7 + g.repro * 1.0 && a.cooldown <= 0 && this.pred.length < 180) {
        const childEnergy = a.energy * 0.32;
        a.energy *= 0.54;
        a.cooldown = 240 + ((rng() * 110) | 0);
        const child = this.makeAgent('pred', a.x + (rng() - 0.5) * 2.4, a.y + (rng() - 0.5) * 2.4, this.mutate(g));
        child.energy = childEnergy; child.cooldown = 190;
        this.pred.push(child);
      }
      if (a.energy <= 0 || a.age > 1000) a.alive = false;
    }

    if ((this.tick & 63) === 0) {
      this.prey = this.prey.filter(a => a.alive);
      this.pred = this.pred.filter(a => a.alive);
    }

    if (this.tick % TICKS_PER_GEN === 0) {
      this.gen++;
      this.prey = this.prey.filter(a => a.alive);
      this.pred = this.pred.filter(a => a.alive);
      this.sample(); this.maybeEvent();
      if (this.gen >= this.targetGenerations) this.finished = true;
    }
  }

  mutate(g) {
    const out = {};
    for (const k of GENE_KEYS) out[k] = clamp(g[k] + gauss(this.rng) * this.mutation * 0.38, 0.03, 0.97);
    return out;
  }

  maybeEvent() {
    if (!this.eventInterval || this.gen % this.eventInterval !== 0) return;
    const order = ['drought', 'plague', 'frost'];
    let type = null;
    for (let k = 1; k <= 3; k++) {
      const t = order[(this.eventCycle + k) % 3];
      if (this.enabled[t]) { type = t; this.eventCycle = (this.eventCycle + k) % 3; break; }
    }
    if (!type) return;
    let plantBefore = 0;
    for (let i = 0; i < N; i++) plantBefore += this.plants[i];
    const beforePrey = this.prey.filter(a => a.alive).length;
    const beforePred = this.pred.filter(a => a.alive).length;
    const losses = { prey: 0, pred: 0, plants: 0 };
    if (type === 'drought') {
      for (let i = 0; i < N; i++) this.plants[i] *= 0.55;
      this.drought = TICKS_PER_GEN * 2;
      let after = 0; for (let i = 0; i < N; i++) after += this.plants[i];
      losses.plants = (plantBefore - after) / Math.max(1, plantBefore);
    } else if (type === 'plague') {
      let killed = 0;
      for (const a of this.prey) if (a.alive && this.rng() < 0.5) { a.alive = false; killed++; }
      this.prey = this.prey.filter(a => a.alive);
      losses.prey = beforePrey ? killed / beforePrey : 0;
    } else {
      for (const a of this.prey) if (a.alive && this.rng() < 0.3) a.alive = false;
      for (const a of this.pred) if (a.alive && this.rng() < 0.28) a.alive = false;
      for (let i = 0; i < N; i++) this.plants[i] *= 0.78;
      this.prey = this.prey.filter(a => a.alive);
      this.pred = this.pred.filter(a => a.alive);
      losses.prey = 0.3; losses.pred = 0.28; losses.plants = 0.22;
    }
    this.events.push({ gen: this.gen, type, losses });
  }

  sample() {
    let plant = 0; for (let i = 0; i < N; i++) plant += this.plants[i];
    const genes = {};
    for (const sp of ['prey', 'pred']) {
      const arr = (sp === 'prey' ? this.prey : this.pred).filter(a => a.alive);
      genes[sp] = {};
      for (const k of GENE_KEYS) {
        let mean = 0; for (const a of arr) mean += a.genes[k]; mean /= Math.max(1, arr.length);
        let varr = 0; for (const a of arr) varr += (a.genes[k] - mean) ** 2; varr /= Math.max(1, arr.length);
        genes[sp][k] = { mean: arr.length ? mean : 0, sd: arr.length ? Math.sqrt(varr) : 0 };
      }
    }
    this.history.push({ gen: this.gen, plants: plant / N, prey: this.prey.filter(a => a.alive).length, pred: this.pred.filter(a => a.alive).length, genes });
  }
}

function summarize(opts, label) {
  const sim = new Sim(opts);
  let guard = 0;
  while (!sim.finished && guard++ < 30000) sim.step();
  const h = sim.history;
  const pick = h.filter(x => x.gen % 4 === 0).map(x => `${x.gen}:${x.prey}/${x.pred}`);
  const maxPrey = Math.max(...h.map(x => x.prey)), maxPred = Math.max(...h.map(x => x.pred));
  const final = h[h.length - 1];
  console.log(label.padEnd(22), 'max', maxPrey, maxPred, '| final', final.prey, final.pred, 'pl', final.plants.toFixed(2), '|', pick.join(' '));
  console.log('  events', sim.events.map(e => e.type[0] + e.gen).join(','), '| genes', h.length > 2 ? GENE_KEYS.map(k => k[0] + ':' + h[h.length - 1].genes.prey[k].mean.toFixed(2)).join(' ') : '');
}

const sets = [
  { label: 'base' },
  { label: 'no predators', predInit: 0 },
  { label: 'slow births', preyInit: 150 },
  { label: 'regrow7', regrowth: 7 },
  { label: 'regrow7-b150', regrowth: 7, preyInit: 150 },
  { label: 'regrow8-b120', regrowth: 8, preyInit: 120 },
  { label: 'pred18', predInit: 18 },
];
for (const s of sets) summarize(s, s.label);

