function scoreRun(opts, gens = 40) {
  const sim = new Sim({ ...opts, targetGenerations: gens, eventInterval: 0 });
  let guard = 0;
  while (!sim.finished && guard++ < 30000) sim.step();
  const h = sim.history;
  const prey = h.map(x => x.prey), pred = h.map(x => x.pred);
  const minP = Math.min(...prey.slice(1)), minD = Math.min(...pred.slice(1));
  const maxP = Math.max(...prey), maxD = Math.max(...pred);
  const final = h[h.length - 1];
  const meanP = prey.reduce((a,b)=>a+b,0)/h.length;
  const cvP = Math.sqrt(prey.reduce((a,b)=>a+(b-meanP)**2,0)/h.length)/Math.max(1,meanP);
  const meanD = pred.reduce((a,b)=>a+b,0)/h.length;
  const cvD = Math.sqrt(pred.reduce((a,b)=>a+(b-meanD)**2,0)/h.length)/Math.max(1,meanD);
  let score = 0;
  if (final.prey > 5 && final.pred > 1) score += 40;
  if (minP > 30) score += 15;
  if (minD > 2) score += 15;
  if (maxP < 2000) score += 8;
  if (maxD < 300) score += 8;
