paintPlants(sim) {
  const data = this.plantImage.data;
  const pal = this.palette;
  const noise = this.cellNoise;
  for (let i = 0; i < CELLS; i++) {
    const raw = sim.plants[i];
    const n = noise[i];
    const mod = 0.76 + (n / 255) * 0.46;
    const p = raw * mod;
    const idx = p <= 0.008 ? 0 : Math.min(63, (p * 63) | 0);
    const c = pal[idx];
    const o = i * 4;
    data[o] = c[0];
    data[o + 1] = c[1];
    data[o + 2] = c[2];
    const alphaMod = 0.68 + (((n >> 3) & 15) / 15) * 0.32;
    data[o + 3] = p <= 0.008 ? 0 : Math.min(255, (c[3] * alphaMod) | 0);
  }
  this.plantCtx.putImageData(this.plantImage, 0, 0);
}

