// basalt outcrops, softened through a low-resolution mask
const sim = this.sim;
if (sim) {
  const mask = document.createElement('canvas');
  mask.width = GRID_W;
  mask.height = GRID_H;
  const mctx = mask.getContext('2d');
  const img = mctx.createImageData(GRID_W, GRID_H);
  for (let y = 0; y < GRID_H; y++) {
    for (let x = 0; x < GRID_W; x++) {
      const i = y * GRID_W + x;
      if (!sim.refuge[i]) continue;
      const n = ((x * 92821) ^ (y * 68917)) & 255;
      const o = i * 4;
      img.data[o] = 9 + (n & 7);
      img.data[o + 1] = 17 + (n % 6);
      img.data[o + 2] = 14 + (n % 4);
      img.data[o + 3] = 208 + (n % 28);
    }
  }
  mctx.putImageData(img, 0, 0);
  c.imageSmoothingEnabled = true;
  c.drawImage(mask, 0, 0, GRID_W, GRID_H, ox, oy, GRID_W * s, GRID_H * s);

  // stone grain
  c.fillStyle = 'rgba(170,164,130,0.075)';
  for (let y = 0; y < GRID_H; y++) {
    for (let x = 0; x < GRID_W; x++) {
      const i = y * GRID_W + x;
      if (!sim.refuge[i]) continue;
      const n = ((x * 37 + y * 71) ^ (x * y)) & 31;
      if (n > 2) continue;
      c.fillRect(ox + x * s + s * (0.2 + (n % 4) * 0.16), oy + y * s + s * (0.25 + (n % 3) * 0.18), 0.8, 0.8);
    }
  }

  // survey contour and top rim
  c.strokeStyle = 'rgba(195,165,111,0.16)';
  c.lineWidth = 0.55;
  c.beginPath();
  c.strokeStyle = 'rgba(195,165,111,0.15)';
  for (let y = 0; y < GRID_H; y++) {
    for (let x = 0; x < GRID_W; x++) {
      const i = y * GRID_W + x;
      if (!sim.refuge[i]) continue;
      const px = ox + x * s;
      const py = oy + y * s;
      if (y === 0 || !sim.refuge[i - GRID_W]) { c.moveTo(px, py); c.lineTo(px + s, py); }
      if (y === GRID_H - 1 || !sim.refuge[i + GRID_W]) { c.moveTo(px, py + s); c.lineTo(px + s, py + s); }
      if (x === 0 || !sim.refuge[i - 1]) { c.moveTo(px, py); c.lineTo(px, py + s); }
      if (x === GRID_W - 1 || !sim.refuge[i + 1]) { c.moveTo(px + s, py); c.lineTo(px + s, py + s); }
    }
  }
  c.stroke();

  c.strokeStyle = 'rgba(215,198,154,0.08)';
  c.lineWidth = 0.7;
  c.beginPath();
  for (let y = 0; y < GRID_H; y++) {
    for (let x = 0; x < GRID_W; x++) {
      const i = y * GRID_W + x;
      if (!sim.refuge[i]) continue;
      if (y === 0 || !sim.refuge[i - GRID_W]) {
        c.moveTo(ox + x * s, oy + y * s + 0.5);
        c.lineTo(ox + (x + 1) * s, oy + y * s + 0.5);
      }
    }
  }
  c.stroke();
}

